#!/usr/bin/env python3
"""Read-only capability inventory for original XREAL Beam + VITURE Luma Pro.

This is a diagnostic instrument, NOT a GrizOS runtime or proof of passthrough AR.
It does not install APKs, change settings, root, remount, or write to the Beam.
"""

import argparse
import hashlib
import json
import re
import shutil
import subprocess
import sys
from pathlib import Path

CAPTURE_COMMANDS = (
    'getprop ro.product.model',
    'getprop ro.build.version.release',
    'pm list features',
    'dumpsys usb',
    'dumpsys display',
)


def parse_adb_devices(output):
    """Return only serials for connected, authorized adb devices, internally."""
    return [line.split()[0] for line in output.splitlines()[1:]
            if len(line.split()) >= 2 and line.split()[1] == 'device']


def parse_usb_devices(output):
    if output is None:
        return {
            'status': 'UNVERIFIED',
            'glasses_control_enumerated': False,
            'camera_enumerated': False,
            'known_device_matches': [],
        }

    matches = []
    # Each Android UsbDevice[] instance is evaluated independently: a VID from
    # one device can never be paired with a PID from a different device.
    for block in re.findall(r'UsbDevice\[([^\]]+)\]', output, re.IGNORECASE | re.DOTALL):
        vid = re.search(r'\b(?:mVendorId|vendorId|idVendor)\s*[:=]\s*(0x[0-9a-f]+|\d+)', block, re.IGNORECASE)
        pid = re.search(r'\b(?:mProductId|productId|idProduct)\s*[:=]\s*(0x[0-9a-f]+|\d+)', block, re.IGNORECASE)
        if not vid or not pid:
            continue
        try:
            vendor, product = int(vid.group(1), 0), int(pid.group(1), 0)
        except ValueError:
            continue
        pair = f'0x{vendor:04x}:0x{product:04x}'
        if pair in ('0x35ca:0x1101', '0x0c45:0x636b') and pair not in matches:
            matches.append(pair)

    return {
        'status': 'OBSERVED' if matches else 'NOT_OBSERVED',
        'glasses_control_enumerated': '0x35ca:0x1101' in matches,
        'camera_enumerated': '0x0c45:0x636b' in matches,
        'known_device_matches': matches,
    }


def parse_display(output):
    if output is None:
        return {'external_display_observed': None, 'status': 'UNVERIFIED'}
    # Do not read a generic 'external display supported' config as proof of an
    # actual connected display. Restrict to an explicit device-info entry.
    found = any(re.search(r'\btype\s*[:= ]\s*EXTERNAL\b', line, re.IGNORECASE)
                for line in output.splitlines() if 'DisplayDeviceInfo' in line)
    return {'external_display_observed': found,
            'status': 'OBSERVED' if found else 'NOT_OBSERVED'}


def make_report(outputs):
    """Derive non-sensitive assertions from adb outputs; preserve SHA digests only.

    Presence in USB enumeration != permission granted, readable frames, received
    IMU messages, video output, or application-level accessibility behavior.
    """
    if not isinstance(outputs, dict):
        raise TypeError('outputs must be a mapping of ADB command names to text')
    features = outputs.get('pm list features')
    if features is None:
        host_feature = None
    else:
        host_feature = 'feature:android.hardware.usb.host' in features

    def get_public_prop(name):
        prop = outputs.get(name)
        if prop is None:
            return None
        return prop.strip().splitlines()[0][:80] if prop.strip() else None

    return {
        'schema': 'gmri.beam-readonly-probe.v1',
        'observation_basis': 'ADB_DEVICE_DUMP_NOT_FUNCTIONAL_STREAM_TEST',
        'device_model': get_public_prop('getprop ro.product.model'),
        'android_version': get_public_prop('getprop ro.build.version.release'),
        'host_usb_feature': host_feature,
        'usb': parse_usb_devices(outputs.get('dumpsys usb')),
        'display': parse_display(outputs.get('dumpsys display')),
        'video_output_test': 'UNTESTED',
        'camera_stream_test': 'UNTESTED',
        'imu_stream_test': 'UNTESTED',
        'passthrough_ar_test': 'UNTESTED',
        'cognitive_continuity_test': 'UNTESTED',
        'evidence': {
            cmd: {'sha256': hashlib.sha256(value.encode('utf-8')).hexdigest(),
                  'byte_count': len(value.encode('utf-8'))}
            for cmd, value in sorted(outputs.items()) if cmd in CAPTURE_COMMANDS
        },
        'limitations': [
            'No functional camera, IMU, or passthrough test is performed.',
            'Lack of USB device enumeration is NOT proof of hardware incompatibility.',
            'No raw USB dumps or ADB serial numbers are included in the summary.',
            'Original XREAL Beam is not manufacturer-supported for VITURE glasses.',
        ],
    }


def _run(cmd, timeout=15):
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout,
                          check=False)
    if proc.returncode != 0:
        raise RuntimeError(f'Command failed (exit {proc.returncode}): {cmd[0]} {cmd[1]}: {proc.stderr[:250]}')
    return proc.stdout


def capture(adb='adb', serial=None):
    if shutil.which(adb) is None:
        raise RuntimeError('ADB not found on this machine. No device test was performed.')
    device_list = parse_adb_devices(_run([adb, 'devices', '-l']))
    if serial is None:
        if len(device_list) != 1:
            raise RuntimeError('Expected exactly one authorized ADB device; no probe performed.')
        serial = device_list[0]
    elif serial not in device_list:
        raise RuntimeError('Selected device is not authorized/connected; no probe performed.')
    outputs = {}
    for command in CAPTURE_COMMANDS:
        try:
            outputs[command] = _run([adb, '-s', serial, 'shell', *command.split()])
        except (RuntimeError, subprocess.TimeoutExpired) as exc:
            # A failed command is UNVERIFIED; never make a false-negative claim.
            outputs.pop(command, None)
            print(f'Observation unavailable: {command}: {type(exc).__name__}', file=sys.stderr)
    return outputs


def main(argv=None):
    p = argparse.ArgumentParser(description='Read-only XREAL Beam / VITURE Luma Pro inventory; no device mutation')
    p.add_argument('--adb', default='adb', help='ADB executable location')
    p.add_argument('--serial', help='Select an authorized ADB device (not included in report)')
    p.add_argument('--output', type=Path, default=Path('beam_observation.json'))
    p.add_argument('--replay-sample', type=Path, help='Read a synthetic fixture instead of accessing hardware')
    args = p.parse_args(argv)
    try:
        if args.replay_sample:
            raw = json.loads(args.replay_sample.read_text(encoding='utf-8'))
            basis = 'SYNTHETIC_FIXTURE_NOT_HARDWARE'
        else:
            raw = capture(adb=args.adb, serial=args.serial)
            basis = 'ACTUAL_ADB_DEVICE_OUTPUT'
        report = make_report(raw)
        report['observation_basis'] = basis
        args.output.write_text(json.dumps(report, indent=2, sort_keys=True) + '\n', encoding='utf-8')
        print(f'Wrote {args.output}. Basis: {basis}')
        return 0
    except (OSError, RuntimeError, json.JSONDecodeError, subprocess.TimeoutExpired) as exc:
        print(f'UNVERIFIED: {exc}', file=sys.stderr)
        return 2


if __name__ == '__main__':
    sys.exit(main())
